-- SkillSprint topic expansion: 20 additional questions across 10 focused topics.
-- Run once in Supabase SQL Editor. Safe to re-run (stable IDs + ON CONFLICT).
DO $seed$
DECLARE q record;
BEGIN
 FOR q IN SELECT * FROM (VALUES
('web-extra-topic-01','web',40,'DOM events','Register a click handler','DOM event listeners connect interface actions to JavaScript functions.','Which method registers a handler for a button click?','button.onClick(run)','button.addEventListener("click", run)','button.listen(run)','button.event("click", run)','b','addEventListener registers a callback for the specified event.','Use the method that explicitly adds an event listener.'),
('web-extra-topic-02','web',41,'DOM events','Stop a form reload','The browser has a default action for form submission.','Which call prevents a form from performing its normal navigation?','event.stop()','event.cancel()','event.preventDefault()','event.pause()','c','preventDefault cancels the browser default form submission behaviour.','Use the method that prevents the default action.'),
('web-extra-topic-03','web',42,'CSS positioning','Anchor an absolute child','An absolutely positioned element is positioned relative to its nearest positioned ancestor.','Which parent declaration commonly establishes the containing block for an absolute child?','position: static','position: relative','display: inline','float: left','b','position:relative establishes a containing block for an absolute descendant.','Set the parent to a non-static position.'),
('web-extra-topic-04','web',43,'CSS positioning','Keep a toolbar fixed','Fixed positioning anchors an element to the viewport.','Which declaration keeps a toolbar fixed to the viewport while scrolling?','position: static','position: relative','position: fixed','position: inherit','c','position:fixed positions an element relative to the viewport in the usual case.','Choose the positioning mode named for staying in place.'),
('logic-extra-topic-01','programming',44,'Strict comparison','Compare value and type','Strict equality checks both value and type without coercion.','What does 5 === "5" return in JavaScript?','true','false','5','undefined','b','A number and a string have different types, so strict equality returns false.','Compare both the value and the data type.'),
('logic-extra-topic-02','programming',45,'Strict comparison','Compare two matching values','Strict equality returns true when values and types match.','What does 5 === 5 return in JavaScript?','true','false','null','undefined','a','Both operands are the same number value and type.','Both sides are numeric five.'),
('logic-extra-topic-03','programming',46,'Callbacks','Recognize a callback','A callback is a function passed to another function to be called later.','In setTimeout(showMessage, 1000), what is showMessage?','A callback function','An array index','A CSS selector','A Promise result','a','showMessage is passed as a function reference and called later.','It is a function supplied as an argument.'),
('logic-extra-topic-04','programming',47,'Callbacks','Pass a function reference','Passing a function reference differs from calling the function immediately.','Which expression passes the function reference rather than its return value?','addEventListener("click", save())','addEventListener("click", save)','addEventListener(save(), "click")','addEventListener("click", "save")','b','save passes the function reference. save() calls the function immediately.','Do not add parentheses when passing the function itself.'),
('database-extra-topic-01','database',48,'DDL','Create a table','CREATE TABLE defines a relational table.','Which statement creates a table named courses?','MAKE TABLE courses;','CREATE TABLE courses (...);','INSERT TABLE courses;','NEW courses TABLE;','b','CREATE TABLE defines a table and its columns and constraints.','Choose the DDL command used to define a table.'),
('database-extra-topic-02','database',49,'DDL','Remove a table definition','DROP TABLE removes a table definition and its data, subject to dependencies.','Which SQL command removes the courses table?','DELETE ROW courses;','DROP TABLE courses;','REMOVE courses;','TRUNCATE DATABASE courses;','b','DROP TABLE removes the table object, not just selected rows.','Choose the command that removes the table structure itself.'),
('database-extra-topic-03','database',50,'Data modeling','Implement many-to-many','A junction table represents a many-to-many relationship.','How is a student-course many-to-many relationship normally implemented?','Comma-separated course names in students','An enrollment table with foreign keys to both tables','Duplicate student fields in courses','One nullable column','b','A junction table stores one row per relationship and references both entities.','Use a table that connects both sides.'),
('database-extra-topic-04','database',51,'Data modeling','Implement one-to-many','A foreign key on the many side points to the one side.','For one department with many students, where is the department foreign key normally stored?','In every department row pointing to a student','In the students table referencing departments','In a separate table for every student','Nowhere; the relationship is only a label','b','Each student row references its department through a foreign key.','The many-side table carries the reference.'),
('security-extra-topic-01','security',52,'Threat modelling','Identify an asset','Threat modelling starts by identifying assets that need protection.','In a student portal, which is a valuable asset?','A decorative footer colour','Student personal records and grades','Browser zoom level','A public logo file only','b','Personal records and grades need confidentiality and integrity protection.','Choose data whose disclosure or tampering would harm students.'),
('security-extra-topic-02','security',53,'Threat modelling','Recognize an attack surface','An attack surface is a point where an attacker could attempt to enter or extract data.','Which item is part of a web application attack surface?','A server API endpoint accepting user input','A printed classroom poster','A powered-off monitor','A colour palette file with no executable code','a','Publicly reachable API endpoints that process untrusted input are part of the attack surface.','Look for a point an attacker can interact with.'),
('security-extra-topic-03','security',54,'Secure communication','Respond to a certificate warning','A certificate warning means the browser cannot verify the expected server identity.','A login site shows an invalid certificate warning. What should you do?','Ignore it and enter your password','Stop and verify the URL or contact the site owner','Disable certificate checks permanently','Install an unknown certificate from a pop-up','b','Do not enter sensitive information until the trust problem is resolved.','Do not bypass a security warning on a login page.'),
('security-extra-topic-04','security',55,'Secure communication','Use secure file transfer','SFTP provides file transfer over SSH.','Which protocol transfers files over an SSH connection?','FTP','SFTP','HTTP','Telnet','b','SFTP uses SSH to provide an encrypted file transfer channel.','It is the file transfer protocol that uses SSH.'),
('tools-extra-topic-01','tools',56,'Node and npm','Understand the lockfile','A lockfile records exact dependency resolutions.','What is the main purpose of package-lock.json?','Store website images','Record resolved dependency versions','Replace package.json scripts','Store user passwords','b','package-lock.json records the dependency tree for repeatable installs.','It locks dependency resolution.'),
('tools-extra-topic-02','tools',57,'Node and npm','Run a build script','npm run executes a named script in package.json.','Which command runs the build script?','npm build','npm run build','node build','git run build','b','npm run build invokes the build script in package.json.','Use npm run followed by the script name.'),
('tools-extra-topic-03','tools',58,'PowerShell','List directory contents','Get-ChildItem lists files and directories.','Which PowerShell command lists files in the current directory?','Get-ChildItem','Get-Location','Set-Location','Get-Process','a','Get-ChildItem returns child items in the current directory.','It retrieves the items inside a folder.'),
('tools-extra-topic-04','tools',59,'PowerShell','Check whether a file exists','Test-Path returns whether a filesystem path exists.','Which PowerShell command checks whether package.json exists?','Get-Path package.json','Test-Path .\package.json','Find-Item package.json','Where-Path package.json','b','Test-Path returns true when the specified path exists.','Use the cmdlet whose name describes testing a path.')
) AS bank(id,path_id,sort_order,category,title,body,question,a,b,c,d,answer,explanation,hint)
 LOOP
  INSERT INTO public.lessons(id,path_id,type,category,title,subtitle,body,content,reward_xp,sort_order,is_published)
  VALUES(q.id,q.path_id,'multiple_choice',q.category,q.title,'Topic practice · Beginner',q.body,
   jsonb_build_object('question',q.question,'options',jsonb_build_array(jsonb_build_object('id','a','label',q.a),jsonb_build_object('id','b','label',q.b),jsonb_build_object('id','c','label',q.c),jsonb_build_object('id','d','label',q.d)),'explanation',q.explanation,'hint',q.hint,'difficulty','beginner'),25,q.sort_order,true)
  ON CONFLICT(id) DO UPDATE SET category=excluded.category,title=excluded.title,body=excluded.body,content=excluded.content,sort_order=excluded.sort_order,is_published=true,updated_at=now();
  INSERT INTO public.lesson_answer_keys(lesson_id,correct_answer) VALUES(q.id,to_jsonb(q.answer::text)) ON CONFLICT(lesson_id) DO UPDATE SET correct_answer=excluded.correct_answer;
 END LOOP;
END
$seed$;
